SELECT json_extract_string(a.state,'$.code') AS code, json_extract_string(a.state,'$.name') AS name, SUM(CASE WHEN json_extract_string(p.state,'$.side') = 'credit' THEN CAST(json_extract(p.state,'$.amount') AS BIGINT) ELSE -CAST(json_extract(p.state,'$.amount') AS BIGINT) END) AS balance, a.object_id AS _of FROM objects a LEFT JOIN objects p ON p.object_type = 'posting' AND json_extract_string(p.state,'$.account') = a.object_id AND json_extract_string(p.state,'$.book') = 'pl-stat' WHERE a.object_type = 'account' AND json_extract_string(a.state,'$.type') = 'equity' GROUP BY 1, 2, 4 ORDER BY 1
